import requests
from bs4 import BeautifulSoup
import pandas as pd
from io import StringIO
def task_func(url, table_id):
    response = requests.get(url)
    response.raise_for_status()
    soup = BeautifulSoup(response.text, 'html.parser')
    table = soup.find('table', id=table_id)
    if table is None:
        raise ValueError("Table with the specified ID not found.")
    rows = table.find_all('tr')
    if not rows:
        return pd.DataFrame()
    data = []
    header = None
    first_row = rows[0]
    header_cells = first_row.find_all('th')
    if header_cells:
        header = [cell.get_text(strip=True) for cell in header_cells]
        data_rows = rows[1:]
    else:
        data_rows = rows
    for row in data_rows:
        cells = row.find_all(['td', 'th'])
        if not cells:
            continue
        data.append([cell.get_text(strip=True) for cell in cells])
    if not data and header is not None:
        return pd.DataFrame(columns=header)
    if header is not None:
        return pd.DataFrame(data, columns=header)
    return pd.DataFrame(data)

import requests
from bs4 import BeautifulSoup
import pandas as pd
from io import StringIO
def task_func(url, table_id):
    response = requests.get(url)
    response.raise_for_status()
    soup = BeautifulSoup(response.text, "html.parser")
    table = soup.find("table", id=table_id)
    if table is None:
        raise ValueError("Table with the specified ID not found.")
    rows = table.find_all("tr")
    if not rows:
        return pd.DataFrame()
    header_cells = rows[0].find_all(["th", "td"])
    headers = [cell.get_text(strip=True) for cell in header_cells] if header_cells else None
    data = []
    data_rows = rows[1:] if headers and len(rows) > 1 else rows if not headers else []
    for row in data_rows:
        cols = row.find_all("td")
        if not cols:
            continue
        data.append([col.get_text(strip=True) for col in cols])
    if not data and not headers:
        return pd.DataFrame()
    if headers and data:
        max_len = max(len(headers), max(len(r) for r in data))
        if len(headers) < max_len:
            headers = headers + [f"Column_{i}" for i in range(len(headers), max_len)]
        normalized_data = []
        for r in data:
            if len(r) < max_len:
                r = r + [None] * (max_len - len(r))
            normalized_data.append(r)
        return pd.DataFrame(normalized_data, columns=headers)
    if headers and not data:
        return pd.DataFrame(columns=headers)
    return pd.DataFrame(data)

