import requests
from lxml import html
import pandas as pd
import sqlite3
def task_func(webpage_url: str, database_name: str = "my_database.db") -> int:
    if not isinstance(webpage_url, str) or not webpage_url:
        return 0
    content = None
    if webpage_url.lower().startswith(("http://", "https://")):
        try:
            response = requests.get(webpage_url)
            response.raise_for_status()
            content = response.text
        except requests.RequestException as e:
            raise e
    else:
        with open(webpage_url, "r", encoding="utf-8") as f:
            content = f.read()
    if not content:
        return 0
    try:
        doc = html.fromstring(content)
        table_elements = doc.xpath("//table")
        if not table_elements:
            return 0
    except Exception:
        return 0
    try:
        tables = pd.read_html(content, flavor="lxml")
    except ValueError:
        return 0
    if not tables:
        return 0
    df = tables[0]
    if df.empty:
        return 0
    try:
        conn = sqlite3.connect(database_name)
        try:
            df.to_sql("my_table", conn, if_exists="replace", index=False)
        finally:
            conn.close()
    except sqlite3.DatabaseError as e:
        raise e
    return len(df)

