import re
import urllib.parse
import requests
import json
def task_func(myString, API_KEY):
    url_pattern = r'https?://[^\s"]+'
    urls = re.findall(url_pattern, myString or "")
    domains = set()
    for url in urls:
        parsed = urllib.parse.urlparse(url)
        netloc = parsed.netloc
        if not netloc:
            continue
        if '@' in netloc:
            netloc = netloc.split('@', 1)[1]
        if ':' in netloc:
            netloc = netloc.split(':', 1)[0]
        if netloc:
            domains.add(netloc)
    result = {}
    for domain in domains:
        try:
            response = requests.get(f"http://ip-api.com/json/{domain}", params={"key": API_KEY})
            if response.status_code == 200:
                try:
                    data = response.json()
                except json.JSONDecodeError:
                    data = None
            else:
                data = None
        except requests.RequestException:
            data = None
        result[domain] = data
    return result

