    url_pattern = r'https?://[^\s<>"\'()]+'
    urls = re.findall(url_pattern, myString if isinstance(myString, str) else "")
    domains = set()
    for url in urls:
        parsed = urllib.parse.urlparse(url)
        netloc = parsed.netloc
        if not netloc and parsed.path:
            pseudo = urllib.parse.urlparse("http://" + parsed.path)
            netloc = pseudo.netloc
        if netloc:
            if ":" in netloc:
                netloc = netloc.split(":", 1)[0]
            if netloc.startswith("www."):
                netloc = netloc[4:]
            if netloc:
                domains.add(netloc)
    results = {}
    for domain in domains:
        try:
            response = requests.get(f"http://ip-api.com/json/{domain}", params={"key": API_KEY}, timeout=10)
            if response.status_code != 200:
                results[domain] = None
                continue
            try:
                data = response.json()
            except json.JSONDecodeError:
                results[domain] = None
                continue
            results[domain] = data
        except requests.RequestException:
            results[domain] = None
    return results

