import re
import json
import requests
def task_func(data_url: str) -> list:
    if not isinstance(data_url, str) or not data_url:
        return "Invalid url input"
    try:
        response = requests.get(data_url)
        text = response.text
        try:
            data = json.loads(text)
            text = json.dumps(data)
        except Exception:
            pass
    except Exception:
        return "Invalid url input"
    bracket_ranges = []
    stack = []
    for i, ch in enumerate(text):
        if ch == '[':
            stack.append(i)
        elif ch == ']' and stack:
            start = stack.pop()
            bracket_ranges.append((start, i))
    def in_brackets(start, end):
        for s, e in bracket_ranges:
            if start >= s and end <= e:
                return True
        return False
    pattern = re.compile(r'[A-Z][a-zA-Z]+')
    names = []
    for m in pattern.finditer(text):
        if not in_brackets(m.start(), m.end()):
            names.append(m.group())
    return names

