from flask import Flask, jsonify
from flask_restful import Resource, Api
import requests
def task_func(api_url, template_folder):
    if not api_url or not isinstance(api_url, str):
        raise ValueError("api_url must be a non-empty string")
    if not template_folder or not isinstance(template_folder, str):
        raise ValueError("template_folder must be a non-empty string")
    app = Flask(__name__, template_folder=template_folder)
    api = Api(app)
    class ExternalAPIResource(Resource):
        def get(self):
            try:
                resp = requests.get(api_url)
                resp.raise_for_status()
                try:
                    data = resp.json()
                except ValueError:
                    return jsonify({"error": "Invalid JSON from external API"}), 502
                return data, resp.status_code
            except requests.HTTPError as e:
                return jsonify({"error": str(e), "status_code": resp.status_code}), resp.status_code
            except requests.RequestException as e:
                return jsonify({"error": str(e)}), 502
    api.add_resource(ExternalAPIResource, "/external-data")
    return app

